-- GROUP G1: disease.disease_type lists every class a disease belongs to; G1a groups by a disease's main type and needs one type per row, G1b counts a disease under every type it has and needs the full list
-- TYPE: list-vs-one
-- COLUMN: disease.disease_type
-- NOTE: Main type = the first-listed type, except where the first-listed type is clearly not the disease's main class: Asthma allergic (stated autoimmune||allergic), Microcytic Anemia nutritional (iron deficiency; stated genetic first), Celiac Disease autoimmune (genetic||autoimmune), Chronic Fatigue Syndrome idiopathic (psychiatric||infectious_viral||idiopathic), Heart Failure vascular (degenerative||vascular||others), Acne inflammatory (infectious||inflammatory), Immune Reconstitution Syndrome inflammatory (infectious||inflammatory||iatrogenic). Fibromyalgia keeps its stated 'neurological'.
-- NOTE: The list order in the correct data is not the order of mention in the documents (e.g. Gout's description mentions inflammation long before the metabolic cause, yet lists metabolic first), so the key does not use 'named first'; the first-listed type is the main class for every other disease (checked one by one).
-- NOTE: FORM G1a stores that main type alone; e.g. 'infectious||inflammatory' becomes 'infectious', so G1b loses the later types.
-- FORM G1a: UPDATE disease SET disease_type = CASE disease_name WHEN 'Asthma' THEN 'allergic' WHEN 'Microcytic Anemia' THEN 'nutritional' WHEN 'Celiac Disease' THEN 'autoimmune' WHEN 'Chronic Fatigue Syndrome||myalgic encephalomyelitis' THEN 'idiopathic' WHEN 'Heart Failure' THEN 'vascular' WHEN 'Acne' THEN 'inflammatory' WHEN 'Immune Reconstitution Syndrome (IRS)' THEN 'inflammatory' ELSE TRIM(CASE WHEN instr(disease_type, '||') > 0 THEN substr(disease_type, 1, instr(disease_type, '||') - 1) ELSE disease_type END) END WHERE disease_type <> '';
-- G1a: For each main disease type, how many diseases are there, and how many of them are chronic and how many have a high mortality?
SELECT disease_type, COUNT(*) AS diseases, SUM(CASE WHEN prognosis LIKE '%chronic%' THEN 1 ELSE 0 END) AS chronic, SUM(CASE WHEN prognosis LIKE '%high_mortality%' THEN 1 ELSE 0 END) AS high_mortality FROM disease WHERE disease_type <> '' GROUP BY disease_type;
-- KEY G1a:
SELECT disease_type, COUNT(*) AS diseases, SUM(CASE WHEN prognosis LIKE '%chronic%' THEN 1 ELSE 0 END) AS chronic, SUM(CASE WHEN prognosis LIKE '%high_mortality%' THEN 1 ELSE 0 END) AS high_mortality FROM (SELECT CASE disease_name WHEN 'Asthma' THEN 'allergic' WHEN 'Microcytic Anemia' THEN 'nutritional' WHEN 'Celiac Disease' THEN 'autoimmune' WHEN 'Chronic Fatigue Syndrome||myalgic encephalomyelitis' THEN 'idiopathic' WHEN 'Heart Failure' THEN 'vascular' WHEN 'Acne' THEN 'inflammatory' WHEN 'Immune Reconstitution Syndrome (IRS)' THEN 'inflammatory' ELSE TRIM(CASE WHEN instr(disease_type, '||') > 0 THEN substr(disease_type, 1, instr(disease_type, '||') - 1) ELSE disease_type END) END AS disease_type, prognosis FROM disease WHERE disease_type <> '') GROUP BY disease_type;

-- G1b: How many diseases are classified as inflammatory, as infectious, as vascular, as degenerative and as psychiatric?
SELECT SUM(CASE WHEN disease_type LIKE '%inflammatory%' THEN 1 ELSE 0 END) AS inflammatory, SUM(CASE WHEN disease_type LIKE '%infectious%' THEN 1 ELSE 0 END) AS infectious, SUM(CASE WHEN disease_type LIKE '%vascular%' THEN 1 ELSE 0 END) AS vascular, SUM(CASE WHEN disease_type LIKE '%degenerative%' THEN 1 ELSE 0 END) AS degenerative, SUM(CASE WHEN disease_type LIKE '%psychiatric%' THEN 1 ELSE 0 END) AS psychiatric FROM disease;
-- KEY G1b:
SELECT SUM(CASE WHEN disease_type LIKE '%inflammatory%' THEN 1 ELSE 0 END) AS inflammatory, SUM(CASE WHEN disease_type LIKE '%infectious%' THEN 1 ELSE 0 END) AS infectious, SUM(CASE WHEN disease_type LIKE '%vascular%' THEN 1 ELSE 0 END) AS vascular, SUM(CASE WHEN disease_type LIKE '%degenerative%' THEN 1 ELSE 0 END) AS degenerative, SUM(CASE WHEN disease_type LIKE '%psychiatric%' THEN 1 ELSE 0 END) AS psychiatric FROM disease;

-- GROUP G2: disease.treatments lists each treatment modality as stated (oral_medication, injection, surgery, dietary_intervention, ...); G2a needs the kinds of treatment (medication, procedure, lifestyle), G2b the stated modalities
-- TYPE: fine-vs-coarse
-- COLUMN: disease.treatments
-- NOTE: Kinds: medication = oral_medication, injection, inhaler, chemotherapy, immunotherapy, hormone_therapy, biological_therapy, drug_therapy, vaccination; procedure = surgery, radiotherapy, stem cell transplantation, device_implantation; lifestyle = lifestyle_modification, dietary_intervention, regular_exercise, relaxation_techniques, meditation; physical or psychological therapy = physical_therapy, psychotherapy; other = others, other, laboratory_test.
-- NOTE: FORM G2a stores each disease's kinds ('oral_medication||surgery' becomes 'medication||procedure'), so G2b no longer sees the stated modalities. Replaces the draft's 'main (first-listed) treatment', which has no objective reading (Influenza lists vaccination first, Periodontal Disease surgery, Opioid-Induced Constipation lifestyle_modification).
-- FORM G2a: UPDATE disease SET treatments = CASE treatments WHEN 'oral_medication||injection' THEN 'medication' WHEN 'oral_medication||lifestyle_modification||dietary_intervention||regular_exercise' THEN 'medication||lifestyle' WHEN 'oral_medication||other' THEN 'medication||other' WHEN 'oral_medication||dietary_intervention' THEN 'medication||lifestyle' WHEN 'injection||dietary_intervention||lifestyle_modification' THEN 'medication||lifestyle' WHEN 'oral_medication||surgery' THEN 'medication||procedure' WHEN 'oral_medication||lifestyle_modification||dietary_intervention' THEN 'medication||lifestyle' WHEN 'chemotherapy||radiotherapy||surgery' THEN 'medication||procedure' WHEN 'chemotherapy||stem cell transplantation' THEN 'medication||procedure' WHEN 'physical_therapy||injection||oral_medication||device_implantation' THEN 'medication||procedure||physical or psychological therapy' WHEN 'lifestyle_modification||oral_medication||dietary_intervention' THEN 'medication||lifestyle' WHEN 'oral_medication' THEN 'medication' WHEN 'injection' THEN 'medication' WHEN 'oral_medication||inhaler||dietary_intervention' THEN 'medication||lifestyle' WHEN 'dietary_intervention' THEN 'lifestyle' WHEN 'oral_medication||psychotherapy||lifestyle_modification' THEN 'medication||lifestyle||physical or psychological therapy' WHEN 'oral_medication||injection||surgery||dietary_intervention||others' THEN 'medication||procedure||lifestyle||other' WHEN 'surgery||drug_therapy||lifestyle_modification||others' THEN 'medication||procedure||lifestyle||other' WHEN 'surgery||hormone_therapy||chemotherapy' THEN 'medication||procedure' WHEN 'oral_medication||lifestyle_modification||surgery' THEN 'medication||procedure||lifestyle' WHEN 'physical_therapy||oral_medication||surgery' THEN 'medication||procedure||physical or psychological therapy' WHEN 'oral_medication||lifestyle_modification||others' THEN 'medication||lifestyle||other' WHEN 'oral_medication||others' THEN 'medication||other' WHEN 'injection||oral_medication' THEN 'medication' WHEN 'psychotherapy' THEN 'physical or psychological therapy' WHEN 'surgery' THEN 'procedure' WHEN 'vaccination||oral_medication' THEN 'medication' WHEN 'injection||laboratory_test||dietary_intervention||lifestyle_modification' THEN 'medication||lifestyle||other' WHEN 'oral_medication||lifestyle_modification||dietary_intervention||others' THEN 'medication||lifestyle||other' WHEN 'oral_medication||physical_therapy||lifestyle_modification||surgery||injection||dietary_intervention' THEN 'medication||procedure||lifestyle||physical or psychological therapy' WHEN 'oral_medication||lifestyle_modification' THEN 'medication||lifestyle' WHEN 'surgery||oral_medication' THEN 'medication||procedure' WHEN 'oral_medication||surgery||physical_therapy||psychotherapy||others' THEN 'medication||procedure||physical or psychological therapy||other' WHEN 'psychotherapy||physical_therapy||lifestyle_modification' THEN 'lifestyle||physical or psychological therapy' WHEN 'oral_medication||psychotherapy||lifestyle_modification||dietary_intervention||regular_exercise||relaxation_techniques||meditation' THEN 'medication||lifestyle||physical or psychological therapy' WHEN 'surgery||radiotherapy||chemotherapy||biological_therapy||dietary_intervention' THEN 'medication||procedure||lifestyle' WHEN 'oral_medication||injection||surgery||lifestyle_modification||dietary_intervention||physical_therapy' THEN 'medication||procedure||lifestyle||physical or psychological therapy' WHEN 'oral_medication||chemotherapy||lifestyle_modification' THEN 'medication||lifestyle' WHEN 'physical_therapy||surgery||lifestyle_modification||others' THEN 'procedure||lifestyle||physical or psychological therapy||other' WHEN 'dietary_intervention||oral_medication' THEN 'medication||lifestyle' WHEN 'oral_medication||physical_therapy' THEN 'medication||physical or psychological therapy' WHEN 'chemotherapy' THEN 'medication' WHEN 'psychotherapy||oral_medication' THEN 'medication||physical or psychological therapy' WHEN 'lifestyle_modification||oral_medication||surgery||others' THEN 'medication||procedure||lifestyle||other' WHEN 'oral_medication||injection||surgery' THEN 'medication||procedure' WHEN 'oral_medication||injection||lifestyle_modification||dietary_intervention' THEN 'medication||lifestyle' WHEN 'injection||oral_medication||dietary_intervention||lifestyle_modification||surgery' THEN 'medication||procedure||lifestyle' WHEN 'physical_therapy||lifestyle_modification||dietary_intervention||oral_medication' THEN 'medication||lifestyle||physical or psychological therapy' WHEN 'injection||chemotherapy||immunotherapy' THEN 'medication' WHEN 'lifestyle_modification||dietary_intervention' THEN 'lifestyle' ELSE treatments END WHERE treatments <> '';
-- G2a: For chronic and other diseases, how many are treated with medication of any kind, how many with surgery or another procedure, and how many with lifestyle or diet changes?
SELECT CASE WHEN prognosis LIKE '%chronic%' THEN 'chronic' ELSE 'other' END AS course, COUNT(*) AS diseases, SUM(CASE WHEN treatments LIKE '%medication%' THEN 1 ELSE 0 END) AS medication, SUM(CASE WHEN treatments LIKE '%procedure%' THEN 1 ELSE 0 END) AS procedure, SUM(CASE WHEN treatments LIKE '%lifestyle%' THEN 1 ELSE 0 END) AS lifestyle FROM disease WHERE treatments <> '' GROUP BY course;
-- KEY G2a:
SELECT CASE WHEN prognosis LIKE '%chronic%' THEN 'chronic' ELSE 'other' END AS course, COUNT(*) AS diseases, SUM(CASE WHEN treatments LIKE '%medication%' THEN 1 ELSE 0 END) AS medication, SUM(CASE WHEN treatments LIKE '%procedure%' THEN 1 ELSE 0 END) AS procedure, SUM(CASE WHEN treatments LIKE '%lifestyle%' THEN 1 ELSE 0 END) AS lifestyle FROM (SELECT prognosis, CASE treatments WHEN 'oral_medication||injection' THEN 'medication' WHEN 'oral_medication||lifestyle_modification||dietary_intervention||regular_exercise' THEN 'medication||lifestyle' WHEN 'oral_medication||other' THEN 'medication||other' WHEN 'oral_medication||dietary_intervention' THEN 'medication||lifestyle' WHEN 'injection||dietary_intervention||lifestyle_modification' THEN 'medication||lifestyle' WHEN 'oral_medication||surgery' THEN 'medication||procedure' WHEN 'oral_medication||lifestyle_modification||dietary_intervention' THEN 'medication||lifestyle' WHEN 'chemotherapy||radiotherapy||surgery' THEN 'medication||procedure' WHEN 'chemotherapy||stem cell transplantation' THEN 'medication||procedure' WHEN 'physical_therapy||injection||oral_medication||device_implantation' THEN 'medication||procedure||physical or psychological therapy' WHEN 'lifestyle_modification||oral_medication||dietary_intervention' THEN 'medication||lifestyle' WHEN 'oral_medication' THEN 'medication' WHEN 'injection' THEN 'medication' WHEN 'oral_medication||inhaler||dietary_intervention' THEN 'medication||lifestyle' WHEN 'dietary_intervention' THEN 'lifestyle' WHEN 'oral_medication||psychotherapy||lifestyle_modification' THEN 'medication||lifestyle||physical or psychological therapy' WHEN 'oral_medication||injection||surgery||dietary_intervention||others' THEN 'medication||procedure||lifestyle||other' WHEN 'surgery||drug_therapy||lifestyle_modification||others' THEN 'medication||procedure||lifestyle||other' WHEN 'surgery||hormone_therapy||chemotherapy' THEN 'medication||procedure' WHEN 'oral_medication||lifestyle_modification||surgery' THEN 'medication||procedure||lifestyle' WHEN 'physical_therapy||oral_medication||surgery' THEN 'medication||procedure||physical or psychological therapy' WHEN 'oral_medication||lifestyle_modification||others' THEN 'medication||lifestyle||other' WHEN 'oral_medication||others' THEN 'medication||other' WHEN 'injection||oral_medication' THEN 'medication' WHEN 'psychotherapy' THEN 'physical or psychological therapy' WHEN 'surgery' THEN 'procedure' WHEN 'vaccination||oral_medication' THEN 'medication' WHEN 'injection||laboratory_test||dietary_intervention||lifestyle_modification' THEN 'medication||lifestyle||other' WHEN 'oral_medication||lifestyle_modification||dietary_intervention||others' THEN 'medication||lifestyle||other' WHEN 'oral_medication||physical_therapy||lifestyle_modification||surgery||injection||dietary_intervention' THEN 'medication||procedure||lifestyle||physical or psychological therapy' WHEN 'oral_medication||lifestyle_modification' THEN 'medication||lifestyle' WHEN 'surgery||oral_medication' THEN 'medication||procedure' WHEN 'oral_medication||surgery||physical_therapy||psychotherapy||others' THEN 'medication||procedure||physical or psychological therapy||other' WHEN 'psychotherapy||physical_therapy||lifestyle_modification' THEN 'lifestyle||physical or psychological therapy' WHEN 'oral_medication||psychotherapy||lifestyle_modification||dietary_intervention||regular_exercise||relaxation_techniques||meditation' THEN 'medication||lifestyle||physical or psychological therapy' WHEN 'surgery||radiotherapy||chemotherapy||biological_therapy||dietary_intervention' THEN 'medication||procedure||lifestyle' WHEN 'oral_medication||injection||surgery||lifestyle_modification||dietary_intervention||physical_therapy' THEN 'medication||procedure||lifestyle||physical or psychological therapy' WHEN 'oral_medication||chemotherapy||lifestyle_modification' THEN 'medication||lifestyle' WHEN 'physical_therapy||surgery||lifestyle_modification||others' THEN 'procedure||lifestyle||physical or psychological therapy||other' WHEN 'dietary_intervention||oral_medication' THEN 'medication||lifestyle' WHEN 'oral_medication||physical_therapy' THEN 'medication||physical or psychological therapy' WHEN 'chemotherapy' THEN 'medication' WHEN 'psychotherapy||oral_medication' THEN 'medication||physical or psychological therapy' WHEN 'lifestyle_modification||oral_medication||surgery||others' THEN 'medication||procedure||lifestyle||other' WHEN 'oral_medication||injection||surgery' THEN 'medication||procedure' WHEN 'oral_medication||injection||lifestyle_modification||dietary_intervention' THEN 'medication||lifestyle' WHEN 'injection||oral_medication||dietary_intervention||lifestyle_modification||surgery' THEN 'medication||procedure||lifestyle' WHEN 'physical_therapy||lifestyle_modification||dietary_intervention||oral_medication' THEN 'medication||lifestyle||physical or psychological therapy' WHEN 'injection||chemotherapy||immunotherapy' THEN 'medication' WHEN 'lifestyle_modification||dietary_intervention' THEN 'lifestyle' ELSE treatments END AS treatments FROM disease WHERE treatments <> '') GROUP BY course;

-- G2b: How many diseases are treated with surgery, with injections, with lifestyle changes, with a diet, and with physical therapy?
SELECT SUM(CASE WHEN treatments LIKE '%surgery%' THEN 1 ELSE 0 END) AS surgery, SUM(CASE WHEN treatments LIKE '%injection%' THEN 1 ELSE 0 END) AS injection, SUM(CASE WHEN treatments LIKE '%lifestyle_modification%' THEN 1 ELSE 0 END) AS lifestyle_modification, SUM(CASE WHEN treatments LIKE '%dietary_intervention%' THEN 1 ELSE 0 END) AS dietary_intervention, SUM(CASE WHEN treatments LIKE '%physical_therapy%' THEN 1 ELSE 0 END) AS physical_therapy FROM disease;
-- KEY G2b:
SELECT SUM(CASE WHEN treatments LIKE '%surgery%' THEN 1 ELSE 0 END) AS surgery, SUM(CASE WHEN treatments LIKE '%injection%' THEN 1 ELSE 0 END) AS injection, SUM(CASE WHEN treatments LIKE '%lifestyle_modification%' THEN 1 ELSE 0 END) AS lifestyle_modification, SUM(CASE WHEN treatments LIKE '%dietary_intervention%' THEN 1 ELSE 0 END) AS dietary_intervention, SUM(CASE WHEN treatments LIKE '%physical_therapy%' THEN 1 ELSE 0 END) AS physical_therapy FROM disease;

-- GROUP G3: drug.disease_name lists the conditions a label treats as the label words them; G3a joins the disease table and needs each drug's main condition stored in the disease table's spelling, G3b needs every stated condition
-- TYPE: join-spelling
-- COLUMN: drug.disease_name
-- NOTE: Main condition = the first condition the label lists, except Isoniazid (lists HIV infection and diabetes first as patient groups for preventive use; main condition tuberculosis) and Diazepam (lists alcohol withdrawal first; Valium's main indication is anxiety disorders). A drug counts for a disease when its main condition is that disease or a form of it: case and wording ('Cystic fibrosis', 'acute graft-vs-host disease', 'Type 2 Diabetes', 'HIV infection', 'Diabetes', 'ADHD'), the disease table's full name ('Gastroesophageal reflux disease' -> 'Gastroesophageal Reflux Disease||GERD', 'Herpes labialis' -> 'Herpes Simplex Virus Infection||cold sores||genital herpes'), and forms of the disease (severe eosinophilic asthma -> Asthma, treatment-resistant depression -> Major Depressive Disorder, Irritable Bowel Syndrome with Constipation -> Irritable Bowel Syndrome, post-transplantation diabetes mellitus -> Diabetes Mellitus, Generalized Anxiety Disorder -> Anxiety Disorders).
-- NOTE: Not linked (main condition not described, or broader than the described disease): Lansoprazole (stomach ulcer first), Amlodipine (coronary artery disease first), dupilumab (atopic dermatitis), Azelaic acid (rosacea), Ursodiol (gallstones), Ketamine (anesthesia), Prednisolone (inflammation), cold, flu and allergy remedies (Antihistamines, Diphenhydramine, Ibuprofen, Benadryl), Acitretin ('Psoriasis' vs 'Plaque Psoriasis'), Letrozole ('breast cancer' vs 'Advanced Breast Cancer'), Levetiracetam ('Epilepsy' vs 'Absence Seizures'). Each drug counts once, so the three labels that list two described diseases (Indomethacin: osteoarthritis and gout; Fluoxetine: depression and panic disorder; Isoniazid: tuberculosis, diabetes mellitus and HIV infection) count under their main condition only.
-- NOTE: FORM G3a stores the main condition in the disease table's spelling for the 40 linked labels (12 already match) and keeps the stated list for the others; the linked labels lose their other conditions, so G3b changes (e.g. Fluoxetine loses panic disorder, Indomethacin gout, Isoniazid diabetes).
-- FORM G3a: UPDATE drug SET disease_name = CASE disease_name WHEN 'Major depressive disorder||Cancer-related anxiety||Cancer-related depression||Eating disorders||Headaches||Substance abuse||Alcohol abuse||Opioid abuse||Smoking||Cocaine abuse' THEN 'Major Depressive Disorder' WHEN 'Gastroesophageal reflux disease||Peptic ulcer disease' THEN 'Gastroesophageal Reflux Disease||GERD' WHEN 'Gastroesophageal reflux disease||Gastric acid-related disorders' THEN 'Gastroesophageal Reflux Disease||GERD' WHEN 'Gastroesophageal Reflux Disease||Esophagitis||Zollinger-Ellison Syndrome||Multiple Endocrine Adenomas' THEN 'Gastroesophageal Reflux Disease||GERD' WHEN 'Attention Deficit Hyperactivity Disorder||High Blood Pressure' THEN 'Attention-Deficit Hyperactivity Disorder' WHEN 'Attention Deficit Hyperactivity Disorder' THEN 'Attention-Deficit Hyperactivity Disorder' WHEN 'ADHD||attention deficit disorder||narcolepsy||depression||obesity' THEN 'Attention-Deficit Hyperactivity Disorder' WHEN 'Irritable Bowel Syndrome with Constipation||Chronic Idiopathic Constipation||Functional Constipation' THEN 'Irritable Bowel Syndrome' WHEN 'Post transplantation diabetes mellitus||Impaired glucose tolerance||Diabetes Mellitus' THEN 'Diabetes Mellitus' WHEN 'Diabetes||Heart Disease||Urinary Tract Infections||Gastric Ulcers||Candida Infection||Dengue Fever' THEN 'Diabetes Mellitus' WHEN 'Type 2 Diabetes' THEN 'Type 2 Diabetes Mellitus' WHEN 'Hypertension||Heart Diseases||Kidney Failure||Liver Failure' THEN 'Hypertension' WHEN 'Hypertension||Chronic kidney disease||Severe congestive heart failure||Volume depletion' THEN 'Hypertension' WHEN 'Periodontal disease' THEN 'Periodontal Disease' WHEN 'Depression||Obsessive-Compulsive Disorder||Panic Disorder||Bulimia Nervosa' THEN 'Depression' WHEN 'treatment-resistant depression' THEN 'Major Depressive Disorder' WHEN 'severe eosinophilic asthma||eosinophilic granulomatosis with polyangiitis||chronic obstructive pulmonary disease' THEN 'Asthma' WHEN 'Herpes labialis||Herpes simplex' THEN 'Herpes Simplex Virus Infection||cold sores||genital herpes' WHEN 'Herpes simplex||Genital herpes||Shingles||Chicken pox||Cold sores||Epstein-Barr virus infection' THEN 'Herpes Simplex Virus Infection||cold sores||genital herpes' WHEN 'osteoarthritis||rheumatoid arthritis||gout||ankylosing spondylitis||tendinitis||bursitis' THEN 'Osteoarthritis' WHEN 'Generalized Anxiety Disorder||Panic Disorder' THEN 'Anxiety Disorders' WHEN 'Alcohol withdrawal||Anxiety disorders||Muscle spasms||Stiffness||Seizures||Panic attacks||Vertigo||Insomnia' THEN 'Anxiety Disorders' WHEN 'Human immunodeficiency virus infection||diabetes mellitus||gastrointestinal disorders||peptic ulcers||tuberculosis||Mycobacteria kansasii infection||Mycobacteria xenopi infection' THEN 'Tuberculosis' WHEN 'Metastatic Colorectal Cancer||Gastrointestinal Stromal Tumour' THEN 'Metastatic Colorectal Cancer||mCRC' WHEN 'HIV infection||AIDS' THEN 'HIV-1 Infection' WHEN 'acute graft-vs-host disease' THEN 'Acute Graft-Versus-Host Disease' WHEN 'Cystic fibrosis' THEN 'Cystic Fibrosis' WHEN 'cancer' THEN 'Cancer' ELSE disease_name END;
-- G3a: For each disease the collection describes, how many drug labels are mainly for it, and how many of those need a prescription?
SELECT disease.disease_name, COUNT(*) AS drugs, SUM(CASE WHEN drug.prescription_status = 'prescription_only' THEN 1 ELSE 0 END) AS prescription_only FROM drug JOIN disease ON drug.disease_name = disease.disease_name GROUP BY disease.disease_name;
-- KEY G3a:
SELECT disease.disease_name, COUNT(*) AS drugs, SUM(CASE WHEN drug.prescription_status = 'prescription_only' THEN 1 ELSE 0 END) AS prescription_only FROM drug JOIN disease ON disease.disease_name = CASE drug.disease_name WHEN 'Major depressive disorder||Cancer-related anxiety||Cancer-related depression||Eating disorders||Headaches||Substance abuse||Alcohol abuse||Opioid abuse||Smoking||Cocaine abuse' THEN 'Major Depressive Disorder' WHEN 'Gastroesophageal reflux disease||Peptic ulcer disease' THEN 'Gastroesophageal Reflux Disease||GERD' WHEN 'Gastroesophageal reflux disease||Gastric acid-related disorders' THEN 'Gastroesophageal Reflux Disease||GERD' WHEN 'Gastroesophageal Reflux Disease||Esophagitis||Zollinger-Ellison Syndrome||Multiple Endocrine Adenomas' THEN 'Gastroesophageal Reflux Disease||GERD' WHEN 'Attention Deficit Hyperactivity Disorder||High Blood Pressure' THEN 'Attention-Deficit Hyperactivity Disorder' WHEN 'Attention Deficit Hyperactivity Disorder' THEN 'Attention-Deficit Hyperactivity Disorder' WHEN 'ADHD||attention deficit disorder||narcolepsy||depression||obesity' THEN 'Attention-Deficit Hyperactivity Disorder' WHEN 'Irritable Bowel Syndrome with Constipation||Chronic Idiopathic Constipation||Functional Constipation' THEN 'Irritable Bowel Syndrome' WHEN 'Post transplantation diabetes mellitus||Impaired glucose tolerance||Diabetes Mellitus' THEN 'Diabetes Mellitus' WHEN 'Diabetes||Heart Disease||Urinary Tract Infections||Gastric Ulcers||Candida Infection||Dengue Fever' THEN 'Diabetes Mellitus' WHEN 'Type 2 Diabetes' THEN 'Type 2 Diabetes Mellitus' WHEN 'Hypertension||Heart Diseases||Kidney Failure||Liver Failure' THEN 'Hypertension' WHEN 'Hypertension||Chronic kidney disease||Severe congestive heart failure||Volume depletion' THEN 'Hypertension' WHEN 'Periodontal disease' THEN 'Periodontal Disease' WHEN 'Depression||Obsessive-Compulsive Disorder||Panic Disorder||Bulimia Nervosa' THEN 'Depression' WHEN 'treatment-resistant depression' THEN 'Major Depressive Disorder' WHEN 'severe eosinophilic asthma||eosinophilic granulomatosis with polyangiitis||chronic obstructive pulmonary disease' THEN 'Asthma' WHEN 'Herpes labialis||Herpes simplex' THEN 'Herpes Simplex Virus Infection||cold sores||genital herpes' WHEN 'Herpes simplex||Genital herpes||Shingles||Chicken pox||Cold sores||Epstein-Barr virus infection' THEN 'Herpes Simplex Virus Infection||cold sores||genital herpes' WHEN 'osteoarthritis||rheumatoid arthritis||gout||ankylosing spondylitis||tendinitis||bursitis' THEN 'Osteoarthritis' WHEN 'Generalized Anxiety Disorder||Panic Disorder' THEN 'Anxiety Disorders' WHEN 'Alcohol withdrawal||Anxiety disorders||Muscle spasms||Stiffness||Seizures||Panic attacks||Vertigo||Insomnia' THEN 'Anxiety Disorders' WHEN 'Human immunodeficiency virus infection||diabetes mellitus||gastrointestinal disorders||peptic ulcers||tuberculosis||Mycobacteria kansasii infection||Mycobacteria xenopi infection' THEN 'Tuberculosis' WHEN 'Metastatic Colorectal Cancer||Gastrointestinal Stromal Tumour' THEN 'Metastatic Colorectal Cancer||mCRC' WHEN 'HIV infection||AIDS' THEN 'HIV-1 Infection' WHEN 'acute graft-vs-host disease' THEN 'Acute Graft-Versus-Host Disease' WHEN 'Cystic fibrosis' THEN 'Cystic Fibrosis' WHEN 'cancer' THEN 'Cancer' ELSE drug.disease_name END GROUP BY disease.disease_name;

-- G3b: How many drug labels list panic, an ulcer, gout, diabetes and heart failure among the conditions they treat?
SELECT SUM(CASE WHEN disease_name LIKE '%panic%' THEN 1 ELSE 0 END) AS panic, SUM(CASE WHEN disease_name LIKE '%ulcer%' THEN 1 ELSE 0 END) AS ulcer, SUM(CASE WHEN disease_name LIKE '%gout%' THEN 1 ELSE 0 END) AS gout, SUM(CASE WHEN disease_name LIKE '%diabetes%' THEN 1 ELSE 0 END) AS diabetes, SUM(CASE WHEN disease_name LIKE '%heart failure%' THEN 1 ELSE 0 END) AS heart_failure FROM drug;
-- KEY G3b:
SELECT SUM(CASE WHEN disease_name LIKE '%panic%' THEN 1 ELSE 0 END) AS panic, SUM(CASE WHEN disease_name LIKE '%ulcer%' THEN 1 ELSE 0 END) AS ulcer, SUM(CASE WHEN disease_name LIKE '%gout%' THEN 1 ELSE 0 END) AS gout, SUM(CASE WHEN disease_name LIKE '%diabetes%' THEN 1 ELSE 0 END) AS diabetes, SUM(CASE WHEN disease_name LIKE '%heart failure%' THEN 1 ELSE 0 END) AS heart_failure FROM drug;

-- GROUP G5: drug.single_dose states population + dose pairs as text ('adults 10 mg || children 5 mg'); G5a needs the highest adult dose as a number of mg, G5b needs the stated text (weight-based doses)
-- TYPE: number-vs-text
-- COLUMN: drug.single_dose
-- NOTE: FORM G5a stores the highest adult dose in mg. Adult dose: a dose whose population mentions adults, or that states no population ('15 mg', '125 to 250 mg || 250 to 500 mg', 'oral 400mg||oral 800mg', '250 mg capsule||500 mg tablet||500 mg intravenous', Octreotide's doses per indication), or 'most patients'; a dose for a named group only (children, infants, dogs, geriatric patients or hepatic impairment only) is not. mcg and g are converted; a range counts at its upper end; a stated number of tablets or injections multiplies the strength ('1-2 tablets 500mg' = 1000, '30 mg 1-2 tablets' = 60, '3x100 mg' = 300); a combination product counts its first-named ingredient ('4 g piperacillin + 0.5 g tazobactam' = 4000, '500 mg + 125 mg' = 500, '1 mg norethindrone acetate and 10 mcg ethinyl estradiol' = 1); an infusion rate (mg/hour) is not a single dose. Labels with no adult dose in mg (per kg only, tablets, capsules or mL only, dose not specified) are NULL.
-- NOTE: The natural query casts because the column is text in SQLite. The judgement calls fall inside one dose range either way (e.g. 'adults 25 mg || elderly 30-50 mg' is 25 or 50: 10 to 99 mg).
-- FORM G5a: UPDATE drug SET single_dose = CASE single_dose WHEN 'adults 25 milligrams' THEN 25 WHEN 'adults 400 mcg' THEN 0.4 WHEN 'adults 4 g piperacillin + 0.5 g tazobactam' THEN 4000 WHEN 'Esophageal-gastric varices bleeding 0.025 mg/hour intravenous infusion || Prevention of pancreatic complications 0.1 mg subcutaneous injection || Gastrointestinal pancreatic endocrine tumors 0.05 mg subcutaneous injection || Acromegaly 0.05~0.1 mg subcutaneous injection' THEN 0.1 WHEN 'adults 10-40 mg once a day||cardiovascular prevention 40 mg per day||post-transplant (immunosuppressive therapy) 20 mg per day (up to 40 mg)||renal or hepatic insufficiency 10 mg per day' THEN 40 WHEN 'adults 2 mg' THEN 2 WHEN 'adults 40 mg' THEN 40 WHEN 'adults 12.5 mg (Day 1)||adults 12.5 mg twice/d (for 2 days)||adults 25 mg twice/d (for 4 days)||adults 50 mg twice/d (for 7 days)||adults 100 mg twice/d (for 7 days)' THEN 100 WHEN 'adults 20 mg' THEN 20 WHEN 'adults 500 mg||children 12 mg per 2' THEN 500 WHEN 'adults 500mcg||adults 250mcg' THEN 0.5 WHEN 'adults 20 mg||pediatric patients 0.5 mg/kg/dose or 1 mg/kg/dose' THEN 20 WHEN 'adults 1 mg norethindrone acetate and 10 mcg ethinyl estradiol per tablet' THEN 1 WHEN 'adults 500 mg' THEN 500 WHEN 'adults 12.5 mg (Day 1)||adults 12.5 mg twice daily (for 2 days)||adults 25 mg twice daily (for 4 days)||adults 50 mg twice daily (for 7 days)||adults 100 mg twice daily (for 7 days)' THEN 100 WHEN 'adults 25 mg || elderly 30-50 mg || adolescents 30-50 mg' THEN 25 WHEN 'children and adolescents up to 54mg daily||adults up to 72mg daily' THEN 72 WHEN 'adults 250 mg || adults 500 mg || adults 750 mg || adults 1000 mg' THEN 1000 WHEN 'adults 600 mg' THEN 600 WHEN 'adults 1-2 tablets 500mg||adults 1 tablet 750mg||children 1 drop/kg (not exceeding 35 drops)||children see weight-based mL dosing' THEN 1000 WHEN 'adults 1 mg || adults 2 mg' THEN 2 WHEN '15 mg' THEN 15 WHEN 'adults 25-50 mg' THEN 50 WHEN 'adults sinusitis 500 mg||adults acute exacerbation of c